using System.Collections.Generic;
using Core;
using Controllers.Rune;
using UnityEngine;

namespace Managers
{
  public class ShopManager : MonoBehaviour
  {
    public static ShopManager Instance { get; private set; }

    [Header("商店配置")]
    [SerializeField] private ShopRuneDatabaseSO shopDatabase;

    private Dictionary<int, int> purchaseRecords = new Dictionary<int, int>();

    void Awake()
    {
      if (Instance == null)
      {
        Instance = this;
        DontDestroyOnLoad(gameObject);
      }
      else
      {
        Destroy(gameObject);
      }
    }

    public bool PurchaseRune(int runeId)
    {
      var config = shopDatabase.GetRuneById(runeId);
      if (config == null)
      {
        Debug.LogError($"[ShopManager] 符文 ID={runeId} 不存在于商店数据库");
        return false;
      }

      if (!IsRuneAvailable(runeId))
      {
        Debug.Log($"[ShopManager] 符文 ID={runeId} 已售罄");
        return false;
      }

      if (!config.allowRepeatPurchase && RuneInventory.HasRune(runeId))
      {
        Debug.Log($"[ShopManager] 符文 ID={runeId} 已拥有，且不允许重复购买");
        return false;
      }

      if (!CoinManager.Instance.SpendCoins(config.price))
      {
        Debug.Log($"[ShopManager] 金币不足，无法购买符文 ID={runeId}");
        return false;
      }

      RecordPurchase(runeId);
      RuneInventory.AddRune(runeId);

      var eventData = new RunePurchasedEventData
      {
        runeId = runeId,
        price = config.price,
        remainingStock = GetRemainingStock(runeId)
      };
      EventChannelLocator.MainContainer?.shopEventChannel?.RaiseRunePurchased(eventData);

      Debug.Log($"[ShopManager] 购买成功：符文 ID={runeId}，花费 {config.price} 金币");
      return true;
    }

    public bool IsRuneAvailable(int runeId)
    {
      var config = shopDatabase.GetRuneById(runeId);
      if (config == null) return false;

      if (!config.isLimitedStock) return true;

      int remaining = GetRemainingStock(runeId);
      return remaining > 0;
    }

    public int GetRemainingStock(int runeId)
    {
      var config = shopDatabase.GetRuneById(runeId);
      if (config == null) return 0;

      if (!config.isLimitedStock) return -1;

      purchaseRecords.TryGetValue(runeId, out int purchased);
      return Mathf.Max(0, config.maxStock - purchased);
    }

    private void RecordPurchase(int runeId)
    {
      if (!purchaseRecords.ContainsKey(runeId))
      {
        purchaseRecords[runeId] = 0;
      }
      purchaseRecords[runeId]++;
    }

    public Dictionary<int, int> GetPurchaseRecords()
    {
      return purchaseRecords;
    }

    public void SetPurchaseRecords(Dictionary<int, int> records)
    {
      purchaseRecords = new Dictionary<int, int>(records);
    }
  }
}

using System.Collections.Generic;
using Core;
using Controllers.Rune;
using UI.Framework;
using UI.Framework.Base;
using UI.Framework.Manager;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UI.Framework.Animation;

public class ShopPanel : UIScreen
{
  [Header("商店符文列表（与符文面板一致）")]
  [SerializeField] private GameObject runeSlotPrefab;
  [SerializeField] private Transform runeSlotContainer;

  [Header("详情信息（只显示名字、描述、价格）")]
  [SerializeField] private GameObject detailPanel;
  [SerializeField] private TextMeshProUGUI detailName;
  [SerializeField] private TextMeshProUGUI detailDescription;
  [SerializeField] private TextMeshProUGUI detailPrice;
  [SerializeField] private Button purchaseButton;

  [Header("金币显示")]
  [SerializeField] private TextMeshProUGUI coinText;

  [SerializeField] private ShopRuneDatabaseSO shopDatabase;

  private List<GameObject> shopRuneSlots = new List<GameObject>();
  private ShopRuneConfigSO selectedRune;
  private RuneSlot selectedRuneSlot;
  private bool isListenerInitialized;

  protected override void Awake()
  {
    screenId = "ShopPanel";
    base.Awake();
    UIManager.Instance.RegisterScreen(this);
  }

  protected override void Start()
  {
    base.Start();
    ResolveDetailReferences();
    InitializeShop();
  }

  protected override void OnBeforeOpen()
  {
    base.OnBeforeOpen();
    EnsureListenerInitialized();
    UpdateCoinDisplay();
    RefreshShopItems();
  }

  protected override void OnAfterClose()
  {
    base.OnAfterClose();
    ClearSelection();
  }

  private void ResolveDetailReferences()
  {
    if (detailName == null)
      detailName = FindChildTMP("DetailName");
    if (detailDescription == null)
      detailDescription = FindChildTMP("DetailDescription");
    if (detailPrice == null)
      detailPrice = FindChildTMP("DetailPrice");
    if (purchaseButton == null)
      purchaseButton = GetComponentInChildren<Button>(true);
  }

  private TextMeshProUGUI FindChildTMP(string name)
  {
    var child = transform.Find(name);
    return child != null ? child.GetComponent<TextMeshProUGUI>() : null;
  }

  private void EnsureListenerInitialized()
  {
    if (isListenerInitialized) return;
    isListenerInitialized = true;

    if (purchaseButton != null)
    {
      purchaseButton.onClick.AddListener(OnPurchaseClicked);
      if (purchaseButton.GetComponent<ButtonFloatAnim>() == null)
        purchaseButton.gameObject.AddComponent<ButtonFloatAnim>();
    }

    var coinChannel = EventChannelLocator.MainContainer?.coinUpdateChannel;
    if (coinChannel != null)
    {
      coinChannel.OnEventRaised += OnCoinUpdated;
    }
  }

  private void InitializeShop()
  {
    EnsureListenerInitialized();

    if (detailPanel != null)
    {
      detailPanel.SetActive(false);
    }
  }

  private void OnCoinUpdated(CoinUpdateData data)
  {
    UpdateCoinDisplay();
  }

  private void RefreshShopItems()
  {
    // 刷新列表时旧 slot 会被销毁，清空选中引用
    selectedRuneSlot = null;

    foreach (var slot in shopRuneSlots)
    {
      Destroy(slot);
    }
    shopRuneSlots.Clear();

    if (shopDatabase == null)
    {
      Debug.LogError("[ShopPanel] shopDatabase 未赋值");
      return;
    }

    if (runeSlotPrefab == null || runeSlotContainer == null)
    {
      Debug.LogError("[ShopPanel] runeSlotPrefab 或 runeSlotContainer 未赋值");
      return;
    }

    foreach (var runeConfig in shopDatabase.shopRunes)
    {
      GameObject slotObj = Instantiate(runeSlotPrefab, runeSlotContainer);
      ShopRuneSlot shopSlot = slotObj.AddComponent<ShopRuneSlot>();

      RuneSlot runeSlot = slotObj.GetComponent<RuneSlot>();
      if (runeSlot != null)
      {
        shopSlot.Initialize(runeSlot, runeConfig, OnRuneSelected);
      }

      shopRuneSlots.Add(slotObj);
    }
  }

  private void UpdateCoinDisplay()
  {
    if (coinText != null)
    {
      int coins = Managers.CoinManager.Instance.GetCoins();
      coinText.text = $"金币: {FormatCoins(coins)}";
    }
  }

  private static string FormatCoins(int amount)
  {
    if (amount < 1000)
      return amount.ToString();
    if (amount < 1000000)
      return (amount / 1000f).ToString("0.#") + "K";
    return (amount / 1000000f).ToString("0.#") + "M";
  }

  private void OnRuneSelected(ShopRuneConfigSO runeConfig, RuneSlot runeSlot)
  {
    // 取消上一个选中项的背景图
    if (selectedRuneSlot != null && selectedRuneSlot != runeSlot)
    {
      selectedRuneSlot.PlayDeselect();
    }

    // 选中当前项，切换背景图
    selectedRuneSlot = runeSlot;
    if (runeSlot != null && !runeSlot.IsSelected)
    {
      runeSlot.PlaySelect();
    }

    selectedRune = runeConfig;

    // 显示详情面板
    if (detailPanel != null)
    {
      detailPanel.SetActive(true);
    }

    // 更新详情文本（不依赖 detailPanel 是否赋值）
    if (detailName != null)
      detailName.text = runeConfig.runeName;
    if (detailDescription != null)
      detailDescription.text = runeConfig.description;
    if (detailPrice != null)
      detailPrice.text = $"{runeConfig.price} ";

    UpdatePurchaseButtonState();

    // 使用RuneInfoChannel展示详情信息，与RunePanel保持一致
    if (runeConfig.runeData != null)
    {
      var runePowers = new Dictionary<int, string>();
      if (runeConfig.runeData.powers != null)
      {
        foreach (var power in runeConfig.runeData.powers)
        {
          runePowers[power.value] = power.label;
        }
      }

      var args = new Core.RuneEquipArgs(
          runeConfig.runeId,
          runeConfig.runeData.runeName,
          runePowers,
          runeConfig.runeData.specialPowerName,
          runeConfig.runeData.specialPowerDescription
      );
      EventChannelLocator.MainContainer.runeInfoChannel.Raise(args);
    }
  }

  private void OnPurchaseClicked()
  {
    if (selectedRune == null)
    {
      Debug.LogWarning("[ShopPanel] 购买失败：未选中符文");
      return;
    }

    Debug.Log($"[ShopPanel] 点击购买，runeId={selectedRune.runeId}, price={selectedRune.price}, allowRepeat={selectedRune.allowRepeatPurchase}");
    bool success = Managers.ShopManager.Instance.PurchaseRune(selectedRune.runeId);
    Debug.Log($"[ShopPanel] 购买结果: {success}");

    if (success)
    {
      RefreshShopItems();
      UpdatePurchaseButtonState();
    }
  }

  private void UpdatePurchaseButtonState()
  {
    if (purchaseButton == null || selectedRune == null) return;

    bool isAvailable = Managers.ShopManager.Instance.IsRuneAvailable(selectedRune.runeId);
    bool hasPurchased = !selectedRune.allowRepeatPurchase && RuneInventory.HasRune(selectedRune.runeId);
    int currentCoins = Managers.CoinManager.Instance.GetCoins();
    bool canAfford = currentCoins >= selectedRune.price;

    purchaseButton.interactable = isAvailable && !hasPurchased && canAfford;

    var btnText = purchaseButton.GetComponentInChildren<TextMeshProUGUI>();
    if (btnText != null)
    {
      btnText.text = hasPurchased ? "已购买" : (purchaseButton.interactable ? "购买" : "不可购买");
    }
  }

  private void ClearSelection()
  {
    if (selectedRuneSlot != null && selectedRuneSlot.IsSelected)
    {
      selectedRuneSlot.PlayDeselect();
    }
    selectedRuneSlot = null;
    selectedRune = null;

    if (detailPanel != null)
    {
      detailPanel.SetActive(false);
    }
  }

  void OnDestroy()
  {
    var coinChannel = EventChannelLocator.MainContainer?.coinUpdateChannel;
    if (coinChannel != null)
    {
      coinChannel.OnEventRaised -= OnCoinUpdated;
    }
  }
}

using Controllers.Rune;
using UI.Framework;
using UnityEngine;
using UnityEngine.UI;

public class ShopRuneSlot : MonoBehaviour
{
  [Header("价格显示")]
  [SerializeField] private Text priceText;
  [SerializeField] private Text stockText;

  private RuneSlot runeSlot;
  private ShopRuneConfigSO shopRuneConfig;
  private System.Action<ShopRuneConfigSO, RuneSlot> onSelected;

  public void Initialize(RuneSlot slot, ShopRuneConfigSO config, System.Action<ShopRuneConfigSO, RuneSlot> selectedCallback)
  {
    runeSlot = slot;
    shopRuneConfig = config;
    onSelected = selectedCallback;

    if (runeSlot != null)
    {
      runeSlot.Setup(config.runeData);
      runeSlot.OnClicked += OnSlotClicked;
    }

    UpdatePriceAndStock();
  }

  private void OnSlotClicked(RuneSlot slot)
  {
    onSelected?.Invoke(shopRuneConfig, runeSlot);
  }

  public void Deselect()
  {
    if (runeSlot != null && runeSlot.IsSelected)
      runeSlot.PlayDeselect();
  }

  public void UpdatePriceAndStock()
  {
    if (priceText != null && shopRuneConfig != null)
    {
      priceText.text = $"{shopRuneConfig.price} 金币";
    }

    if (stockText != null && shopRuneConfig != null)
    {
      if (shopRuneConfig.isLimitedStock)
      {
        int remaining = Managers.ShopManager.Instance.GetRemainingStock(shopRuneConfig.runeId);
        stockText.text = remaining > 0 ? $"库存: {remaining}" : "已售罄";
        stockText.gameObject.SetActive(true);
      }
      else
      {
        stockText.gameObject.SetActive(false);
      }
    }

    var image = GetComponent<Image>();
    if (image == null) return;

    bool isPurchased = shopRuneConfig != null
        && !shopRuneConfig.allowRepeatPurchase
        && RuneInventory.HasRune(shopRuneConfig.runeId);
    float alpha = image.color.a;
    image.color = isPurchased
        ? new Color(0.5f, 0.5f, 0.5f, alpha)
        : new Color(1f, 1f, 1f, alpha);
  }

  void OnDestroy()
  {
    if (runeSlot != null)
    {
      runeSlot.OnClicked -= OnSlotClicked;
    }
  }
}

using System;
using Controllers.Rune;

namespace Core
{
    /// <summary>
    /// 符文购买事件数据
    /// </summary>
    public struct RunePurchasedEventData
    {
        public int runeId;          // 购买的符文ID
        public int price;           // 购买价格
        public int remainingStock;  // 剩余库存（如果是限量商品）
    }

    /// <summary>
    /// 商店事件通道接口
    /// </summary>
    public interface IShopEventChannel
    {
        event Action<RunePurchasedEventData> OnRunePurchased;
        event Action OnShopOpened;
        event Action OnShopClosed;

        void RaiseRunePurchased(RunePurchasedEventData data);
        void RaiseShopOpened();
        void RaiseShopClosed();
    }

    /// <summary>
    /// 商店事件通道实现
    /// </summary>
    public class ShopEventChannel : IShopEventChannel
    {
        public event Action<RunePurchasedEventData> OnRunePurchased;
        public event Action OnShopOpened;
        public event Action OnShopClosed;

        public void RaiseRunePurchased(RunePurchasedEventData data)
        {
            OnRunePurchased?.Invoke(data);
        }

        public void RaiseShopOpened()
        {
            OnShopOpened?.Invoke();
        }

        public void RaiseShopClosed()
        {
            OnShopClosed?.Invoke();
        }
    }
}

