namespace Managers
{
    /// <summary>
    /// 金币系统管理器（Application 层）
    ///
    /// 职责：
    /// - 管理金币的增删查（运行时内存值）
    /// - 提供金币计算公式 CalculateCoins(kills, totalDamage)
    /// - 通过 EventChannel 与 Presentation 层通信
    ///
    /// 持久化说明：
    /// - 不再使用 PlayerPrefs，由 SaveManager 统一管理
    /// - SaveManager.LoadGame() → SetCoins() 恢复
    /// - SaveManager.SaveGame() → GetCoins() 收集
    ///
    /// 通信方式：
    /// 输出 → coinUpdateChannel（金币变化时更新 UI）
    ///
    /// 设计说明：
    /// - 纯本地单例，无需网络同步
    /// - 只含一种货币（金币）
    /// - CalculateCoins() 为纯计算方法，不修改余额
    /// </summary>
    public class CoinManager : MonoBehaviour
    {
        public static CoinManager Instance { get; private set; }

        // ========== 配置项（Inspector 可调） ==========

        [Header("金币计算参数")]
        [SerializeField] private int baseCoinPerKill = 50;
        [SerializeField] private float damageCoinFactor = 0.1f;

        // ========== 运行时状态 ==========

        private int currentCoins;

        // ========== 单例生命周期 ==========

        void Awake()
        {
            if (Instance == null)
            {
                Instance = this;
                DontDestroyOnLoad(gameObject);
            }
            else
            {
                Destroy(gameObject);
            }
        }

        void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        // ========== 公开 API ==========

        /// <summary>获取当前金币总数</summary>
        public int GetCoins()
        {
            return currentCoins;
        }

        /// <summary>增加金币，并触发 UI 更新</summary>
        public void AddCoins(int amount)
        {
            if (amount <= 0) return;

            currentCoins += amount;
            RaiseCoinUpdate(amount);
        }

        /// <summary>
        /// 消费金币
        /// </summary>
        /// <param name="amount">消费金额</param>
        /// <returns>是否消费成功（余额不足返回 false）</returns>
        public bool SpendCoins(int amount)
        {
            if (amount <= 0) return false;
            if (currentCoins < amount) return false;

            currentCoins -= amount;
            RaiseCoinUpdate(-amount);
            return true;
        }

        /// <summary>直接设置金币数（用于存档恢复、GM 指令等）</summary>
        public void SetCoins(int amount)
        {
            if (amount < 0) amount = 0;

            int delta = amount - currentCoins;
            currentCoins = amount;
            RaiseCoinUpdate(delta);
        }

        // ========== 金币计算公式 ==========

        /// <summary>
        /// 根据击杀数和总伤害计算应获得的金币数
        /// 公式：kills * baseCoinPerKill + floor(totalDamage * damageCoinFactor)
        /// </summary>
        /// <param name="kills">本局击杀数</param>
        /// <param name="totalDamage">本局总伤害量</param>
        /// <returns>经公式计算后应得的金币数</returns>
        /// <remarks>
        /// 此方法为纯计算，不修改余额。
        /// 调用方应使用返回值调用 AddCoins() 来实际发放金币。
        /// </remarks>
        public int CalculateCoins(int kills, int totalDamage)
        {
            int killReward = kills * baseCoinPerKill;
            int damageReward = Mathf.FloorToInt(totalDamage * damageCoinFactor);
            return killReward + damageReward;
        }

        /// <summary>重置金币为 0（用于测试）</summary>
        public void ResetCoins()
        {
            currentCoins = 0;
            RaiseCoinUpdate(0);
        }

        /// <summary>
        /// 广播当前金币数到事件通道，用于 UI 初始化。
        /// 进入大厅时调用，确保所有金币显示组件获得初始值。
        /// </summary>
        public void BroadcastCurrentCoins()
        {
            RaiseCoinUpdate(0);
        }

        // ========== 事件通信 ==========

        /// <summary>
        /// 发送金币更新事件到 Presentation 层
        /// </summary>
        private void RaiseCoinUpdate(int delta)
        {
            if (EventChannelLocator.MainContainer?.coinUpdateChannel == null) return;

            var data = new CoinUpdateData(currentCoins, delta);
            EventChannelLocator.MainContainer.coinUpdateChannel.Raise(data);
        }
    }
}

using System.Collections;
using Core;
using DG.Tweening;
using TMPro;
using UI.Framework.Base;
using UnityEngine;

namespace UI.Framework
{
    /// <summary>
    /// 顶部消息通知 Widget
    ///
    /// 职责：
    /// - 收到消息后用 DOTween 滑入，停留指定时间后通过 Animator trigger "Close" 播放关闭动画
    /// - 自动监听：符文购买成功 / 任务完成 / Boss击杀完成
    ///
    /// 挂在 Top 层 Canvas 上作为常驻 Widget
    /// </summary>
    public class TopNotice : UIWidget
    {
        [Header("TopNotice UI")]
        [SerializeField] private TextMeshProUGUI messageText;
        [SerializeField] private Animator animator;

        [Header("TopNotice 动画设置")]
        [Tooltip("消息停留时间（秒）")]
        [SerializeField] private float displayDuration = 2.5f;
        [Tooltip("滑入动画时长（秒）")]
        [SerializeField] private float animDuration = 0.4f;
        [Tooltip("滑入距离（从上方偏移多少滑入）")]
        [SerializeField] private float slideDistance = 100f;

        private static readonly int CloseHash = Animator.StringToHash("Close");

        private CanvasGroup _canvasGroup;
        private RectTransform _rectTransform;
        private Vector2 _originalPosition;

        private bool _isShowing;
        private Coroutine _autoHideCoroutine;
        private Tween _openTween;
        private Tween _hideTween;

        // ──────────────────────────────────────────────
        //  AutoBindComponents
        // ──────────────────────────────────────────────

        protected override void AutoBindComponents()
        {
            if (messageText == null)
                messageText = FindComponentInChildren<TextMeshProUGUI>();

            if (animator == null)
                animator = GetComponentInChildren<Animator>();

            _rectTransform = GetComponent<RectTransform>();
            _originalPosition = _rectTransform.anchoredPosition;

            _canvasGroup = GetComponent<CanvasGroup>();
            if (_canvasGroup == null)
                _canvasGroup = gameObject.AddComponent<CanvasGroup>();

            SetVisible(false);
        }

        // ──────────────────────────────────────────────
        //  事件订阅 / 取消
        // ──────────────────────────────────────────────

        protected override void SubscribeEvents()
        {
            var container = EventChannelLocator.MainContainer;
            if (container == null) return;

            if (container.shopEventChannel != null)
                container.shopEventChannel.RegisterListener(OnRunePurchased);

            if (container.bossDeathChannel != null)
                container.bossDeathChannel.RegisterListener(OnBossDeath);

            if (container.taskUIChannel != null)
                container.taskUIChannel.RegisterListener(OnTaskUIEvent);
        }

        protected override void UnsubscribeEvents()
        {
            var container = EventChannelLocator.MainContainer;
            if (container == null) return;

            if (container.shopEventChannel != null)
                container.shopEventChannel.UnregisterListener(OnRunePurchased);

            if (container.bossDeathChannel != null)
                container.bossDeathChannel.UnregisterListener(OnBossDeath);

            if (container.taskUIChannel != null)
                container.taskUIChannel.UnregisterListener(OnTaskUIEvent);
        }

        // ──────────────────────────────────────────────
        //  事件回调
        // ──────────────────────────────────────────────

        private void OnRunePurchased(RunePurchasedEventData data)
        {
            Show("购买成功");
        }

        private void OnBossDeath()
        {
            Show("击杀完成");
        }

        private void OnTaskUIEvent(TaskUIUpdateData data)
        {
            if (data.eventType == TaskUIEventType.NoticeData)
            {
                if (data.data != null && data.data.Contains("任务完成"))
                    Show("任务完成");
            }
        }

        // ──────────────────────────────────────────────
        //  公共 API
        // ──────────────────────────────────────────────

        /// <summary>显示一条顶部通知</summary>
        public void Show(string message)
        {
            if (messageText != null)
                messageText.text = message;

            if (_autoHideCoroutine != null)
                StopCoroutine(_autoHideCoroutine);

            KillOpenTween();
            _isShowing = true;
            SetVisible(true);

            // 初始状态：上方偏移 + 透明
            _rectTransform.anchoredPosition = _originalPosition + new Vector2(0, slideDistance);
            _canvasGroup.alpha = 0f;

            // DOTween 滑入动画：位移归位 + 淡入
            _openTween = DOTween.Sequence()
                .Join(_rectTransform.DOAnchorPos(_originalPosition, animDuration).SetEase(Ease.OutQuad))
                .Join(_canvasGroup.DOFade(1f, animDuration).SetEase(Ease.OutQuad));

            _autoHideCoroutine = StartCoroutine(AutoHideAfter(displayDuration));
        }

        /// <summary>手动隐藏通知（Animator Close + DOTween 逐渐透明）</summary>
        public void Hide()
        {
            if (!_isShowing) return;

            if (_autoHideCoroutine != null)
            {
                StopCoroutine(_autoHideCoroutine);
                _autoHideCoroutine = null;
            }

            KillOpenTween();
            KillHideTween();
            _isShowing = false;

            // Animator 触发 Close 状态转换
            if (animator != null)
                animator.SetTrigger(CloseHash);

            // DOTween 同时逐渐变透明
            _hideTween = _canvasGroup.DOFade(0f, animDuration).SetEase(Ease.InQuad)
                .OnComplete(() => SetVisible(false));
        }

        // ──────────────────────────────────────────────
        //  内部协程
        // ──────────────────────────────────────────────

        private IEnumerator AutoHideAfter(float delay)
        {
            yield return new WaitForSeconds(delay);
            Hide();
        }

        // ──────────────────────────────────────────────
        //  工具方法
        // ──────────────────────────────────────────────

        private void SetVisible(bool visible)
        {
            if (_canvasGroup != null)
            {
                _canvasGroup.alpha = visible ? 1f : 0f;
                _canvasGroup.blocksRaycasts = visible;
                _canvasGroup.interactable = visible;
            }
        }

        private void KillOpenTween()
        {
            if (_openTween != null && _openTween.IsActive())
            {
                _openTween.Kill();
                _openTween = null;
            }
        }

        private void KillHideTween()
        {
            if (_hideTween != null && _hideTween.IsActive())
            {
                _hideTween.Kill();
                _hideTween = null;
            }
        }

        protected override void OnDisable()
        {
            base.OnDisable();
            KillOpenTween();
            KillHideTween();
        }
    }
}

